+/* 결과 화면 틀의 머리 막대와 지표 이름 줄. classic에는 없던 요소라 기본은 숨기고 카드 층에서 켠다. */
+.visualBar,
+.visualMetrics {
+  display: none;
+}
+
+/*
+  디자인 개편 카드 층(S15P21E205-425). 위 규칙은 classic 그대로 두고, 새 디자인에서만 지표 띠 항목과
+  백테스트 그림을 카드로 담는다. 흐르는 띠·곡선이 그려지는 움직임과 한 칸 높이 규칙은 그대로다.
+*/
+:global(:root:not([data-design='classic'])) .storySection { border-bottom: 0; }
