+
+/* 지표 띠: 항목마다 카드. 두 묶음이 같은 폭이어야 -50% 이동에서 이음매가 보이지 않으므로 간격을 묶음 끝에도 둔다. */
+:global(:root:not([data-design='classic'])) .conveyorViewport { padding-block: 2px; border: 0; }
