+  border-radius: var(--thorp-radius-control);
+  background: var(--thorp-surface);
+}
+:global(:root:not([data-design='classic'])) .textCta:hover { padding-right: 16px; border-color: var(--thorp-line-control-hover); background: var(--thorp-surface-muted); }
+
+/* 백테스트 그림: 결과 화면 한 장을 담은 카드. 틀이 생기면 남는 높이가 빈 칸으로 보이므로 키는 내용에 맞추고, 화면이 낮을 때만 줄어든다. */
+:global(:root:not([data-design='classic'])) .backtestVisual {
